def as_list(value):
	if isinstance(value, str):
		try:
			value = json.loads(value)
		except:
			value = value.split("\n")
	if not isinstance(value, list):
		return []
	return [str(v) for v in value if str(v).strip()]

def split_row(raw, count):
	parts = [p.strip() for p in str(raw).split("|")]
	while len(parts) < count:
		parts.append("")
	return parts

def slugify(value):
	chars = [c if c.isalnum() else "-" for c in str(value).lower()]
	slug = "".join(chars)
	while "--" in slug:
		slug = slug.replace("--", "-")
	return slug.strip("-") or "item"

def minutes(value):
	try:
		bits = str(value).strip().split(":")
		return int(bits[0]) * 60 + int(bits[1])
	except:
		return -1

def clock(total):
	return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

def number(value, fallback):
	try:
		result = float(value)
		return result if result > 0 else fallback
	except:
		return fallback

def ems(value, table):
	total = 0.0
	for ch in str(value).upper():
		total = total + table.get(ch, 0.22) + 0.02
	return round(total, 3)

def anchor(day, start, room, slug):
	# a session's id: day, start and the room's first word ("thu-0930-main"); whole-room breaks
	# carry no room. The hero, the lineup and the speaker index link to the same ids.
	key = slug(day)[:3]
	stamp = str(start).strip().replace(":", "")
	place = str(room).strip().lower()
	if place in ["", "all", "every room", "everywhere"]:
		return key + "-" + stamp
	return key + "-" + stamp + "-" + slug(place.split(" ")[0])

def weekday(iso):
	names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
	months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]
	offsets = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
	try:
		bits = str(iso).strip().split("-")
		year = int(bits[0])
		month = int(bits[1])
		day = int(bits[2])
		y = year - 1 if month < 3 else year
		index = (y + y // 4 - y // 100 + y // 400 + offsets[month - 1] + day) % 7
		return {"name": names[index], "date": str(day) + " " + months[month - 1]}
	except:
		return {"name": "", "date": ""}

SIX = {"0": 0.203, "1": 0.188, "2": 0.203, "3": 0.219, "4": 0.219, "5": 0.22, "6": 0.234, "7": 0.172, "8": 0.213, "9": 0.234, "A": 0.219, "B": 0.25, "C": 0.25, "D": 0.25, "E": 0.188, "F": 0.188, "G": 0.25, "H": 0.25, "I": 0.141, "J": 0.25, "K": 0.234, "L": 0.188, "M": 0.313, "N": 0.25, "O": 0.25, "P": 0.234, "Q": 0.25, "R": 0.25, "S": 0.219, "T": 0.219, "U": 0.25, "V": 0.219, "W": 0.344, "X": 0.203, "Y": 0.219, "Z": 0.172, " ": 0.116, ",": 0.094, ".": 0.109, "?": 0.211, "!": 0.126, "'": 0.133, "\u2019": 0.238, "&": 0.24, "-": 0.266, "\u20ac": 0.263, "$": 0.225, "\u00a3": 0.268, ":": 0.109, ";": 0.109, "(": 0.172, ")": 0.172, "/": 0.172, "+": 0.313, "%": 0.529, "\u00c4": 0.219, "\u00d6": 0.25, "\u00dc": 0.22, "\u00c5": 0.219, "\u00c9": 0.188, "\u00c8": 0.188, "\u00c1": 0.219, "\u00c0": 0.219, "\u00cd": 0.141, "\u00d3": 0.25, "\u00da": 0.22, "\u00d1": 0.25, "\u00c7": 0.228, "\u00d8": 0.228, "\"": 0.219}

people = []
widest = 0.0
try:
	for raw in as_list(props.get("speakers")):
		parts = split_row(raw, 4)
		if not parts[0]:
			continue
		widest = max(widest, ems(parts[0], SIX))
		slots = []
		bits = [b.strip() for b in parts[2].split(",") if b.strip()]
		for i in range(len(bits)):
			words = bits[i].split(" ")
			at = words[1] if len(words) > 1 else ""
			more = i < len(bits) - 1
			slots.append({"label": bits[i], "href": "#" + anchor(words[0], at, parts[3], slugify), "more": more, "joiner": "and" if more else ""})
		people.append({"id": slugify(parts[0]), "name": parts[0], "studio": parts[1], "slots": slots, "room": parts[3]})
except:
	people = []
component.people = people
component.wmax = str(widest if widest > 0.5 else 2.9)
